-- V1: the payment_db schema exactly as it was before Flyway (until then Hibernate's
-- ddl-auto created it). PostgreSQL. Flyway connects as payment_svc, so payment_svc owns
-- every table it creates.
--
-- On the existing database this file is NOT run: spring.flyway.baseline-on-migrate=true
-- marks the database as "already at version 1" and leaves the data alone.
-- On a new, empty database Flyway runs it and creates everything.
-- Never edit this file after it has been applied: add V2__..., V3__... for changes.

-- GENERATED BY DEFAULT AS IDENTITY = auto-increment id (sequence payments_id_seq)
CREATE TABLE payments (
    id bigint GENERATED BY DEFAULT AS IDENTITY,
    amount numeric(38,2),
    created_at timestamp(6) without time zone,
    order_id bigint,
    status character varying(20),
    transaction_id character varying(255),
    updated_at timestamp(6) without time zone,
    user_id bigint,
    order_cancelled boolean DEFAULT false NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT payments_pkey PRIMARY KEY (id),
    -- at most one payment per order
    CONSTRAINT payments_order_id_unique UNIQUE (order_id)
);

CREATE INDEX idx_payments_user_created ON payments USING btree (user_id, created_at);

-- Outbox: events written in the same transaction as the change, sent to Kafka by OutboxPublisher
CREATE TABLE outbox_events (
    id bigint GENERATED BY DEFAULT AS IDENTITY,
    created_at timestamp(6) without time zone NOT NULL,
    event_key character varying(100) NOT NULL,
    payload text NOT NULL,
    sent_at timestamp(6) without time zone,
    status character varying(20) NOT NULL,
    topic character varying(100) NOT NULL,
    CONSTRAINT outbox_events_pkey PRIMARY KEY (id),
    CONSTRAINT outbox_events_status_check CHECK (status IN ('PENDING', 'SENT'))
);

CREATE INDEX idx_outbox_status_id ON outbox_events USING btree (status, id);

-- ShedLock: makes each @Scheduled job run on one instance at a time
-- (was created by postgres-init/02-payment-shedlock.sql before Flyway)
CREATE TABLE shedlock (
    name character varying(64) NOT NULL,
    lock_until timestamp(3) without time zone NOT NULL,
    locked_at timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP(3) NOT NULL,
    locked_by character varying(255) NOT NULL,
    CONSTRAINT shedlock_pkey PRIMARY KEY (name)
);
